["11736"]={["Title"]="Осквернение огня", ["Objectives"]="ЗавершеноОскверните большой костер Альянса в Острогорье!", ["Description"]="", ["Progress"]="", ["Completion"]="", ["Comments"]="Костер находится на краю моста, который пересекает каньон, на другой стороне от крепости Тандерлорд, где видны форпост Бладмаул и крепость Блейдспейр. Координаты: 50.1 59.0", ["Coords"]={{x=50.1, y=59}}, ["ZoneId"]=nil, ["Level"]=nil, ["RequiredLevel"]=1, ["Faction"]=nil, ["StartNpcId"]=nil, ["EndNpcId"]=nil, ["PrevQuestId"]=nil, ["NextQuestId"]=nil, ["Type"]="Solo", ["StartNpcName"]=nil, ["EndNpcName"]=nil},
["11735"]={["Title"]="Осквернение огня", ["Objectives"]="ЗавершеноОскверните большой костер Альянса на острове Лазурной Дымки!", ["Description"]="", ["Progress"]="", ["Completion"]="", ["Comments"]="Котёл находится примерно в районе 45.5 52, к югу и западу от Azure Watch.", ["Coords"]={{x=45.5, y=52}}, ["ZoneId"]=nil, ["Level"]=nil, ["RequiredLevel"]=1, ["Faction"]=nil, ["StartNpcId"]=nil, ["EndNpcId"]=nil, ["PrevQuestId"]=nil, ["NextQuestId"]=nil, ["Type"]="Solo", ["StartNpcName"]=nil, ["EndNpcName"]=nil},
